package ru.neverland.mintespionage.service;
import java.nio.file.*;import java.util.concurrent.*;import org.bukkit.configuration.file.YamlConfiguration;import ru.neverland.core.*;
public final class SpyPurchaseRepository {
    private final Path file;private final AcknowledgedState<SpyPurchases.State> store;private volatile boolean readable;
    public SpyPurchaseRepository(Path file){this.file=file;store=new AcknowledgedState<>(file,SpyPurchases.State.empty(),SpyPurchaseRepository::encode,"NeverLand-spy-purchase-write");}
    public void load()throws Exception{readable=false;var state=SpyPurchases.State.empty();if(!Files.notExists(file)){if(Files.size(file)>32*1024*1024)throw new java.io.IOException("Архив покупок слишком большой");var y=SafeYaml.load(file);SafeYaml.keys(y,"schema","purchases");if(SafeYaml.integer(y,"schema")!=1)throw new java.io.IOException("Неверная схема покупок разведки");state=SpyPurchases.JSON.fromJson(SafeYaml.text(y,"purchases"),SpyPurchases.State.class);if(state==null)throw new java.io.IOException("Пустой архив покупок");}store.loaded(state);readable=true;}
    private static String encode(SpyPurchases.State value)throws java.io.IOException{var y=new YamlConfiguration();y.set("schema",1);y.set("purchases",SpyPurchases.JSON.toJson(value));String text=y.saveToString();if(text.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>32*1024*1024)throw new java.io.IOException("Архив покупок заполнен");return text;}
    public SpyPurchases.State state(){return store.get();}public boolean readable(){return readable;}public boolean writable(){return readable&&store.writable();}public boolean busy(){return store.busy();}public CompletionStage<SpyPurchases.State> put(SpyPurchases.Purchase p){if(!writable())return CompletableFuture.failedFuture(new IllegalStateException("Покупки разведки временно недоступны"));var before=store.get();return store.commit(before,before.put(p));}public CompletionStage<Void> prepareClose(){return store.prepareClose();}
}
